<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="dv-content"><h1>Tableau croisé dynamique</h1><div class="dv-card"><div style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><div class="dv-form-group"><label class="dv-label">Agrégateur</label><select id="aggregation" class="dv-select"><option value="Count">Compter</option><option value="Sum">Somme des quantités</option><option value="Average">Moyenne des quantités</option></select></div><button id="loadPivot" class="dv-btn dv-btn-primary">Charger les données</button><button id="exportCsv" class="dv-btn dv-btn-outline">Exporter CSV</button></div></div><div class="dv-card"><div id="pivot" style="min-height:180px;padding:20px;color:var(--text-muted);text-align:center">Cliquez sur « Charger les données ».</div></div></div><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/pivottable/2.23.0/pivot.min.css"><script src="<?= base_url('assets/jquery.js') ?>"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/jqueryui/1.12.1/jquery-ui.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pivottable/2.23.0/pivot.min.js"></script><script>document.getElementById('loadPivot').onclick=async()=>{const target=document.getElementById('pivot');target.textContent='Chargement en cours…';try{const r=await fetch('<?= site_url('api/donnees') ?>',{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(!Array.isArray(data)||!data.length)throw new Error('Aucune donnée disponible');const agg=document.getElementById('aggregation').value;$(target).empty().pivotUI(data,{rows:['District'],cols:['TypeMedicament'],vals:agg==='Count'?[]:['Quantite'],aggregatorName:agg,rendererName:'Table'},true)}catch(e){target.innerHTML='<div class="dv-alert dv-alert-danger">Impossible de charger le tableau : '+e.message+'</div>'}};document.getElementById('exportCsv').onclick=()=>{const t=document.querySelector('#pivot table');if(!t)return alert('Chargez un tableau avant l’export.');const csv=[...t.rows].map(r=>[...r.cells].map(c=>'"'+c.innerText.replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='tdc.csv';a.click()};</script><?= $this->endSection() ?>
